package chapter13;
import javax.swing.*; import java.awt.*; import java.awt.geom.*; import java.awt.event.*; import java.util.*;
public class ScreenSaverRandomLines extends JPanel implements ActionListener{Random r=new Random();Timer timer=new Timer(100,this);int limit=100,count;JTextField field=new JTextField("100",5);ScreenSaverRandomLines(){setLayout(new BorderLayout());JPanel p=new JPanel();p.add(new JLabel("Lines before clearing:"));p.add(field);add(p,BorderLayout.NORTH);field.addActionListener(e->setLimit());timer.start();}void setLimit(){try{limit=Math.max(1,Integer.parseInt(field.getText()));}catch(Exception e){}}protected void paintComponent(Graphics g){super.paintComponent(g);for(int i=0;i<count;i++)g.drawLine(r.nextInt(Math.max(1,getWidth())),r.nextInt(Math.max(1,getHeight())),r.nextInt(Math.max(1,getWidth())),r.nextInt(Math.max(1,getHeight())));}public void actionPerformed(ActionEvent e){setLimit();count++;if(count>limit)count=1;repaint();}public static void main(String[]a){ConcentricCirclesArc.show("13.20",new ScreenSaverRandomLines(),700,450);}}
